import z3

# Create a boolean variable for each possible edge
edges = {}
for i in range(8):
    for j in range(i + 1, 8):
        edges[(i, j)] = z3.Bool(f"e_{i}_{j}")

solver = z3.Solver()

# Add known edges
known_edges = [(2,6), (0,6), (4,7), (6,7), (3,7)]
for i in range(8):
    for j in range(i + 1, 8):
        if (i, j) in known_edges:
            solver.add(edges[(i, j)] == True)

# Add minimum degree constraint
for i in range(8):
    degree = []
    for j in range(8):
        if i < j:
            degree.append(z3.If(edges[(i, j)], 1, 0))
        elif i > j:
            degree.append(z3.If(edges[(j, i)], 1, 0))
    solver.add(z3.Sum(degree) >= 3)

if solver.check() == z3.sat:
    m = solver.model()
    result = []
    for i in range(8):
        for j in range(i + 1, 8):
            if m.evaluate(edges[(i, j)]):
                result.append((i, j))
    print("SAT")
    print(result)
else:
    print("UNSAT")
